SELECT COUNT(*) AS treatment_count
FROM treatments
WHERE treatment_date >= '2023-03-01' AND treatment_date < '2024-03-01';

SELECT COUNT(*) AS appointment_count
FROM appointments
WHERE appointment_date >= '2023-04-01' AND appointment_date < '2023-07-01';

SELECT COUNT(*) AS bill_count
FROM billing
WHERE bill_date >= '2023-03-15' AND bill_date <= '2023-04-15';

SELECT treatment_type, ROUND(AVG(cost), 2) AS avg_cost
FROM treatments
GROUP BY treatment_type;

SELECT status, COUNT(*) AS appointment_count
FROM appointments
GROUP BY status;

SELECT COUNT(*) AS cancelled_appointment_count
FROM appointments
WHERE status = 'Cancelled';

SELECT insurance_provider, COUNT(DISTINCT patient_id) AS patient_count
FROM patients
GROUP BY insurance_provider;

SELECT COUNT(*) AS female_patient_count
FROM patients
WHERE gender = 'F';

SELECT COUNT(*) AS bill_count
FROM billing
WHERE bill_date >= '2023-01-01' AND bill_date < '2024-01-01';

SELECT COUNT(*) AS bill_count
FROM billing
WHERE bill_date >= '2022-12-01' AND bill_date < '2023-01-01';

SELECT bill_date AS paid_date
FROM billing
WHERE payment_status = 'Paid';

SELECT treatment_type, COUNT(*) AS treatment_count
FROM treatments
GROUP BY treatment_type;

SELECT treatment_type, COUNT(*) AS treatment_count
FROM treatments
GROUP BY treatment_type;
